import kotlin.math.min

fun gcd(a: Int, b: Int): Int {
    var a = a
    var b = b
    if (a > b) {
        val temp = a
        a = b
        b = temp
    }
    if (a == 0 || b == 0) {
        return a + b
    }
    while (true) {
        val remain = b % a
        if (remain == 0) {
            return a
        }
        b = a
        a = remain
    }
}

